export function PermissionPrompt({
  appName = "{{appName}}",
  permission = "{{permission}}",
  rememberChoice = {{rememberChoice}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 300, padding: 18, borderRadius: 12, boxSizing: "border-box", border: "1px solid #24143018", boxShadow: "0 10px 24px rgba(36,20,48,.14)" }}>
      <span style={{ display: "inline-flex", color: accent, marginBottom: 8 }}>
        <svg width="24" height="24" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3l7 3v6c0 4.5-3 7.5-7 9-4-1.5-7-4.5-7-9V6l7-3Z" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinejoin="round" /></svg>
      </span>
      <p style={{ margin: "0 0 12px" }}>Allow <strong>{appName}</strong> to access your {permission}?</p>
      {rememberChoice && <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13, marginBottom: 14, color: "#24143099" }}><input type="checkbox" />Remember my choice</label>}
      <div style={{ display: "flex", gap: 10 }}>
        <button type="button" style={{ flex: 1, padding: 9, borderRadius: 8, fontWeight: 700, cursor: "pointer", font: "inherit", background: "transparent", border: "1.5px solid #24143030", color: "#241430" }}>Block</button>
        <button type="button" style={{ flex: 1, padding: 9, borderRadius: 8, fontWeight: 700, cursor: "pointer", font: "inherit", background: accent, border: "none", color: "#14351f" }}>Allow</button>
      </div>
    </div>
  );
}
